def stat(d):
    x = np.asarray(d["environment"], dtype=float)
    a = x[:-1] - x[:-1].mean(axis=0)
    b = x[1:] - x[1:].mean(axis=0)
    den = np.sqrt((a ** 2).sum(axis=0) * (b ** 2).sum(axis=0))
    ok = den > 0
    if not np.any(ok):
        return 0.0
    r = (a * b).sum(axis=0)[ok] / den[ok]
    return float(np.mean(r))
